/**
 * 组装「Cloudflare Worker」的部署目录：把 33 MB 的题库数据换成瘦身版。
 *
 * 为什么需要这一步
 * ----------------
 * `src/core/qbank-source.data.js` 是 33 MB（835 道题，其中 28 MB 是 HTML：
 * stemHtml 18 MB + analysisHtml 9.4 MB + answerHtml 0.5 MB）。
 * router → registry → qbank 在**模块初始化**时就把它整个解析掉，实测
 * 185 ms CPU、135 MB 堆。Workers 的内存上限是 128 MB，于是冷启动的 isolate
 * 直接超限，表现为「时好时坏」的 `503 / error code 1105`：
 * 热实例正常，冷实例必挂。
 *
 * 解法的边界
 * ----------
 * Worker 只做 API，不渲染题干 HTML —— 浏览器要的 HTML 在静态资源里
 * （`public/qbank/q/<i>.json` 与 `public/qbank/map.html`，共 26 MB，走 CDN）。
 * 所以部署包里可以安全地把三个 HTML 字段去掉：835 道题的其余字段（题干文本、
 * 选项、答案、解析文本、知识点与方法标签）一个不少，瘦身后 3.3 MB，
 * 堆占用从 135 MB 降到 27 MB。
 *
 * 换句话说：**题库页面完全不受影响**（它读的是 public/ 下的静态 JSON），
 * 受影响的只有「服务端把题库 HTML 当参考原文再下发」这一件事，
 * 而那条路本来就没在 Worker 上跑过。
 *
 * 用法
 * ----
 *   node scripts/build-cf-bundle.mjs [--out .tmp-cf-bundle]
 *   cd .tmp-cf-bundle && npx wrangler deploy
 *
 * 产物目录里是一份**完整可部署**的副本：api/ + src/ + public/ + wrangler.jsonc，
 * 只有 src/core/qbank-source.data.js 被换掉。源仓库一个字节都不改。
 */

import { copyFileSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const ROOT = resolve(import.meta.dirname, '..');
const OUT = resolve(ROOT, process.argv.includes('--out') ? process.argv[process.argv.indexOf('--out') + 1] : '.tmp-cf-bundle');

/** 部署目录需要带着走的东西；其余（docs/tests/脚本）不进包。 */
const ENTRIES = ['api', 'src', 'public', 'package.json', 'wrangler.jsonc'];

/** 只在这几个字段上是 HTML；其余字段服务端要原样用。 */
const HTML_FIELDS = ['stemHtml', 'analysisHtml', 'answerHtml'];

const sizeOf = (p) => {
  try {
    return statSync(p).isDirectory() ? null : statSync(p).size;
  } catch {
    return null;
  }
};

function slimQuestions(source) {
  return source.map((q) => {
    const copy = { ...q };
    for (const f of HTML_FIELDS) delete copy[f];
    return copy;
  });
}

function renderSlimModule(questions) {
  return [
    '// AUTO-GENERATED by scripts/build-cf-bundle.mjs — 不要手改，也不要提交回仓库。',
    '// 与 src/core/qbank-source.data.js 的唯一差别：去掉三个冗余的 HTML 字段（浏览器要的那份在 public/qbank/ 下）。',
    `export const QBANK_SOURCE=${JSON.stringify(questions)};`,
    '',
  ].join('\n');
}

/**
 * 递归复制目录。
 *
 * 为什么不用 `fs.cpSync`：在本机 Windows + Node 24 上，它对目录调用会直接
 * 把进程打崩（退出码 127、无任何报错输出），而单文件 `copyFileSync` 正常。
 * 这个脚本要在开发机上跑，所以自己走一遍目录树，只用最稳的那几个 API。
 */
function copyTree(from, to) {
  mkdirSync(to, { recursive: true });
  for (const entry of readdirSync(from)) {
    const src = join(from, entry);
    const dest = join(to, entry);
    if (statSync(src).isDirectory()) copyTree(src, dest);
    else copyFileSync(src, dest);
  }
}

async function main() {
  const srcFile = join(ROOT, 'src/core/qbank-source.data.js');
  const before = sizeOf(srcFile);

  const { QBANK_SOURCE } = await import(pathToFileURL(srcFile).href);
  if (!Array.isArray(QBANK_SOURCE) || QBANK_SOURCE.length === 0) {
    throw new Error(`${srcFile} 没有导出非空的 QBANK_SOURCE —— 先确认文件没被换掉`);
  }

  const slim = slimQuestions(QBANK_SOURCE);
  const slimText = renderSlimModule(slim);

  rmSync(OUT, { recursive: true, force: true });
  mkdirSync(OUT, { recursive: true });
  for (const entry of ENTRIES) {
    const from = join(ROOT, entry);
    const dest = join(OUT, entry);
    if (statSync(from).isDirectory()) copyTree(from, dest);
    else copyFileSync(from, dest);
  }
  writeFileSync(join(OUT, 'src/core/qbank-source.data.js'), slimText);

  const after = slimText.length;
  const kb = (n) => `${(n / 1048576).toFixed(1)} MB`;
  console.log(`题库：${slim.length} 道`);
  console.log(`qbank-source.data.js：${kb(before)} → ${kb(after)}（省 ${kb(before - after)}）`);
  console.log(`部署目录：${OUT}`);
  console.log('下一步：cd ' + OUT + ' && npx wrangler deploy');
  console.log('');
  console.log('注意：题库页面（public/qbank/**）是静态资源，不经过 worker，不受这次瘦身影响。');
}

// 只有被直接执行时才组装；被测试 import 进来时只拿走纯函数，不动盘。
const invokedDirectly = process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url;
if (invokedDirectly) {
  main().catch((err) => {
    console.error('[✗] ' + (err?.message || err));
    process.exit(1);
  });
}

export { slimQuestions, renderSlimModule, HTML_FIELDS };
